def S(n):
    return sum(int(d) for d in str(n))

def check(n):
    for k in range(38):
        if S(n + k) % 11 == 0:
            return False
    return True

candidates = {
    "A": 999981,
    "B": 459,
    "C": 291,
    "D": 110999990,
    "E": 1999981,
    "F": 10**10 - 1
}

results = {}
for label, n in candidates.items():
    results[label] = check(n)

print(f"Candidate results: {results}")

# Search for small n
found_n = None
for n in range(1, 10000):
    if check(n):
        found_n = n
        break
print(f"Smallest n found in range(1, 10000): {found_n}")

